 parser=argparse.ArgumentParser();parser.add_argument('--evidence-dir',type=Path,required=True);parser.add_argument('--output',type=Path,required=True);a=parser.parse_args()
 if a.output.name.endswith('-private.json') or a.output.resolve().is_relative_to(a.evidence_dir.resolve()):raise ValueError('Private output boundary')
 sources={f:(r.ROOT/f).read_bytes() for f in FILES};catalog,rls,hashes=r.load(a.evidence_dir.resolve())
